    mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 201, validToken),
    mcpCall(cfg, cfg.url, "tools/call", { name: "calendar_list", arguments: {} }, 202, validToken),
  ]);
