node -e "
const { spawn, execFile } = require('child_process');
const mock = spawn(process.execPath, ['mcp-acceptance/mock/lifecycle-server.js'], { env: { ...process.env, MOCK_PORT: '4001', MOCK_WORLD: 'current' }, stdio: 'pipe' });
setTimeout(async () => {
  const results = [];
  for (const [name, harness] of [
    ['oauth-lifecycle', 'mcp-acceptance/oauth-lifecycle.js'],
    ['security-isolation', 'mcp-acceptance/security-isolation.js'],
  ]) {
    const r = await new Promise((resolve) => {
      execFile(process.execPath, [harness, '--url', 'http://127.0.0.1:4001/mcp', '--issuer', 'http://127.0.0.1:4002', '--timeout-ms', '5000'], { timeout: 20000 }, (error, stdout, stderr) => {
        resolve({ name, exitCode: error ? error.code : 0 });
      });
    });
    results.push(r);
  }
  mock.kill();
  console.log('=== Current production behavior (expect exit 1 for both) ===');
  for (const r of results) {
    console.log(r.name + ': exit ' + r.exitCode + (r.exitCode === 1 ? ' (RED - correct)' : ' (WRONG)'));
  }
  process.exit(0);
}, 1000);
"

